const cfg=window.SOLIDFORM_SUPABASE||{};let sb=null;const demo=!(cfg.url&&cfg.publishableKey);
const rand=id=>document.querySelector(id);const msg=(text,bad=false)=>{const el=rand('#form-message');if(!el)return;el.textContent=text;el.className=`form-message show${bad?' error':''}`};
async function client(){if(demo)return null;if(sb)return sb;const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');sb=createClient(cfg.url,cfg.publishableKey);return sb}
document.querySelectorAll('[data-demo-mode]').forEach(el=>el.textContent=demo?'Interactive demo · connect Supabase to go live':'Live Supabase environment');
const demoProjects=[{id:'p1',title:'Full kitchen renovation',place:'Randburg, Gauteng',category:'Kitchen',budget:'R120k–R180k',quote:'Initial customer estimate: R132k–R156k',date:'Start within 1–2 months'},{id:'p2',title:'Three-bedroom home addition',place:'Midrand, Gauteng',category:'Addition',budget:'R650k–R900k',quote:'Initial customer estimate: R710k–R838k',date:'Flexible start'},{id:'p3',title:'Roof waterproofing & repairs',place:'Roodepoort, Gauteng',category:'Roofing',budget:'R35k–R65k',quote:'Initial customer estimate: R42k–R50k',date:'Urgent'}];
function projectHTML(p){return `<article class="project-card"><div><small>${p.category}</small><h3>${p.title}</h3><p>${p.place}</p><div class="project-meta"><span>${p.date}</span><span>${p.quote}</span></div></div><div class="project-price">${p.budget}<br><button class="button primary" data-interest="${p.id}" type="button">View & respond</button></div></article>`}
const list=rand('#project-list');if(list){list.innerHTML=demoProjects.map(projectHTML).join('');list.addEventListener('click',e=>{if(e.target.matches('[data-interest]'))msg('Project opened. In the live system, a verified contractor can submit an application and detailed quote.');})}
const reg=rand('#contractor-registration');if(reg)reg.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(reg);if(demo){msg('Demo registration complete. Connect the Supabase URL and publishable key to create real accounts and securely upload documents.');return}try{const s=await client();const email=fd.get('email'),password=fd.get('password'),full_name=fd.get('representative_name');const {data,error}=await s.auth.signUp({email,password,options:{data:{role:'contractor',full_name}}});if(error)throw error;if(!data.user)throw new Error('Account could not be created.');const services=fd.getAll('services');const payload={user_id:data.user.id,account_type:fd.get('account_type'),legal_name:fd.get('legal_name'),trading_name:fd.get('trading_name')||null,company_registration_number:fd.get('company_registration_number')||null,representative_name:full_name,province:fd.get('province'),city:fd.get('city'),years_experience:Number(fd.get('years_experience')||0),team_size:Number(fd.get('team_size')||1),service_categories:services,cidb_number:fd.get('cidb_number')||null,nhbrc_number:fd.get('nhbrc_number')||null,bio:fd.get('bio')||null};const {error:pe}=await s.from('contractor_profiles').insert(payload);if(pe)throw pe;for(const input of reg.querySelectorAll('input[type=file][data-doc]')){const file=input.files[0];if(!file)continue;const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'-');const path=`${data.user.id}/${input.dataset.doc}/${Date.now()}-${safe}`;const {error:ue}=await s.storage.from('contractor-documents').upload(path,file);if(ue)throw ue;const {error:de}=await s.from('contractor_documents').insert({contractor_id:data.user.id,document_type:input.dataset.doc,storage_path:path,file_name:file.name,status:'pending'});if(de)throw de}msg(data.session?'Registration submitted for review.':'Account created. Confirm your email, then sign in to finish document submission.')}catch(err){msg(err.message||'Registration failed.',true)}});
const projectForm=rand('#project-form');if(projectForm)projectForm.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(projectForm);if(demo){msg('Project published in demo mode. Verified contractors would now see the brief and its initial estimate.');return}try{const s=await client();const {data:{user}}=await s.auth.getUser();if(!user)throw new Error('Please sign in as a customer first.');const {error}=await s.from('projects').insert({customer_id:user.id,title:fd.get('title'),category:fd.get('category'),description:fd.get('description'),suburb:fd.get('suburb'),province:fd.get('province'),budget_min:Number(fd.get('budget_min')),budget_max:Number(fd.get('budget_max')),initial_estimate_min:Number(fd.get('estimate_min')||0),initial_estimate_max:Number(fd.get('estimate_max')||0),initial_quote_snapshot:{source:'customer project form'},status:'open'});if(error)throw error;msg('Your project is live for verified contractors.')}catch(err){msg(err.message,true)}});
if(projectForm){try{const q=JSON.parse(localStorage.getItem('solidform_quote_draft')||'null');if(q){projectForm.elements.estimate_min.value=q.estimateMin||'';projectForm.elements.estimate_max.value=q.estimateMax||'';projectForm.elements.description.value=`Services: ${(q.services||[]).join(', ')}\nApprox. area: ${q.area||''} m²\nFinish: ${q.finish||''}\nTiming: ${q.timing||''}\nNotes: ${q.details||''}`;projectForm.elements.suburb.value=q.location==='Not provided'?'':q.location}}catch{}}
const review=rand('#review-form');if(review)review.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(review);if(demo){msg('Thank you. Your demo review was submitted for moderation.');return}try{const s=await client();const {data:{user}}=await s.auth.getUser();if(!user)throw new Error('Please sign in to review a completed project.');const payload=Object.fromEntries(fd);['workmanship','communication','timeliness','value','cleanliness'].forEach(k=>payload[k]=Number(payload[k]));payload.customer_id=user.id;const {error}=await s.from('reviews').insert(payload);if(error)throw error;msg('Review submitted for moderation.')}catch(err){msg(err.message,true)}});
const authForm=rand('#customer-auth');if(authForm)authForm.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(authForm);if(demo){msg('Demo customer session started. Connect Supabase to create a real account.');return}try{const s=await client();const action=e.submitter?.value||'signin';let result;if(action==='signup')result=await s.auth.signUp({email:fd.get('email'),password:fd.get('password'),options:{data:{role:'customer',full_name:fd.get('full_name')}}});else result=await s.auth.signInWithPassword({email:fd.get('email'),password:fd.get('password')});if(result.error)throw result.error;msg(action==='signup'&&!result.data.session?'Check your email to confirm the account.':'Signed in. Your customer workspace is ready.')}catch(err){msg(err.message,true)}});
const verify=rand('#verification-form');if(verify)verify.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(verify);if(demo){msg('Demo decision recorded. Live decisions require an authenticated administrator and create a permanent review trail.');return}try{const s=await client();const {data:{user}}=await s.auth.getUser();if(!user)throw new Error('Administrator sign-in required.');const payload={document_id:fd.get('document_id'),reviewer_id:user.id,decision:fd.get('decision'),verification_method:fd.get('verification_method'),official_register_url:fd.get('official_register_url'),reference_checked:fd.get('reference_checked'),name_matched:fd.get('name_matched')==='on',number_matched:fd.get('number_matched')==='on',validity_checked:fd.get('validity_checked')==='on',notes:fd.get('notes')};const {error}=await s.from('document_verifications').insert(payload);if(error)throw error;const {error:ue}=await s.from('contractor_documents').update({status:payload.decision}).eq('id',payload.document_id);if(ue)throw ue;msg('Verification decision saved.')}catch(err){msg(err.message,true)}});
